  const data: RestampResult = result.data;
  console.log(`Restamped ${data.handoffId}`);
  console.log(`  base_sha: ${data.base_sha}`);
  if (data.base_wiki_sha) {
    console.log(`  base_wiki_sha: ${data.base_wiki_sha}`);
  }
  return 0;
}

export async function run(args: string[]): Promise<number> {
  const showHelp = getFlag(args, '--help') || getFlag(args, '-h');
  const showVersion = getFlag(args, '--version') || getFlag(args, '-v');

  if (showVersion) {
    console.log(`kb dispatch v${VERSION}`);
    return 0;
  }

  const command = args.find((arg) => !arg.startsWith('-'));
  if (showHelp || !command) {
    console.log(HELP_TEXT);
    return 0;
  }

  let exitCode: number;
  switch (command) {
    case 'check-environment':
      exitCode = await cmdCheckEnvironment();
      break;
    case 'init-dispatch':
      exitCode = await cmdInitDispatch(args);
      break;
    case 'create-handoff':
      exitCode = await cmdCreateHandoff(args);
      break;
    case 'cleanup':
      exitCode = await cmdCleanup(args);
      break;
    case 'status':
      exitCode = await cmdStatus(args);
      break;
    case 'dispatch':
      exitCode = await cmdDispatch(args);
      break;
    case 'wait-for-run':
      exitCode = await cmdWaitForRun(args);
      break;
    case 'restamp':
      exitCode = await cmdRestamp(args);
      break;
    default:
      console.error(`Unknown command: ${command}`);
      console.error('Run with --help to see available commands.');
      return 1;
  }

  // WK-0153: post-command unhandled-runs banner to stderr
  const dir = getFlagValue(args, '--dir');
  if (dir) {
    try {
      const unhandledResult = await listUnhandledRuns(resolve(dir));
      if (unhandledResult.ok) {
        for (const run of unhandledResult.data) {
          console.error(`⚑ UNHANDLED: ${run.handoff_id} ${run.status} ${run.completed_at} → ${run.branch}`);
        }
      } else {
        console.error(`⚑ unhandled-runs check failed: ${unhandledResult.error}`);
      }
    } catch {
      console.error('⚑ unhandled-runs check failed: unexpected error');
    }
  }

  return exitCode;
}

