  inferenceProvider?: string;
  /**
   * Host-side, deterministic mount-write manifest (WK-0164): per-`export_mount`
   * files whose mtime is newer than the run's start time, walked by
   * pipeline.ts after the worker exits — never a worker self-report. Renders
   * as a `## Mount Writes` section when non-empty; omitted entirely when
   * absent/empty.
   */
  mountWrites?: Array<{ mountPath: string; files: string[] }>;
}

export interface CaptureResult {
  responsePath: string;
  responseContent: string;
}

export interface ProvenanceWriteBack {
  /** Fields to merge into the HO frontmatter */
  fields: Record<string, string | boolean | string[]>;
}

/**
 * DEC-0010 mechanical verdict vocabulary. Computed exclusively from
 * delivery-gate facts and mode deliverable checks (`deriveVerdict` below) —
 * no worker input is ever consulted. `timed_out`/`cancelled` are set at the
 * pipeline/controller level on paths that never reach `writeResponseDoc` at
 * all (e.g. a watchdog-killed worker); `deriveVerdict` itself never returns
 * them.
 */
type ResponseOutcome = 'delivered' | 'failed' | 'refused' | 'timed_out' | 'cancelled';

/**
 * Branch naming is a fixed convention (`dispatch/<handoffId>`), meaningful
 * only once a commit actually landed; refused/no-op/conflict/error outcomes
 * carry no branch value.
 */
function deriveBranch(handoffId: string, delivery: DeliveryOutcome): string {
  if (delivery.status === 'delivered') {
    return delivery.branch || `dispatch/${handoffId}`;
  }
  return '';
}

/**
 * `deriveVerdict`'s return: the mechanical outcome plus a machine-set reason
 * code for every non-`delivered` result. `deliveryMethod` (WK-0125/DEC-0037)
 * is a SEPARATE observability field from `reason` — it names how a
 * `code_review`/`redteam` result was obtained (`structured` from a valid
 * recovery block vs. `prose_fallback` from the chat transcript), not to be
 * confused with `DeliveryOutcome`/the git delivery-gate result the rest of
 * this module calls `delivery`. Unset for `implement`/`research`, where the
 * structured/prose fork doesn't apply.
 */
interface VerdictResult {
  outcome: ResponseOutcome;
  reason?: string;
  deliveryMethod?: 'structured' | 'prose_fallback';
}

/**
 * Mechanical verdict ladder (DEC-0010 rule 2 — "completion is mechanical;
 * workers never assert done/not-done"). Every branch reads only delivery-gate
 * facts, the handoff's mode, and (for research/redteam crash detection only)
 * the Pi adapter's facts-only process classification — never the worker's
 * chat text, and never a worker-authored self-report file as authority. The
 * one exception is `recoveryEvidence.valid` for code_review/redteam (DEC-0037,
 * below) — even there the branch reads only whether extraction/validation
 * succeeded, never the worker's narrative content inside the block.
 *
 * DEC-0037 role asymmetry (reverses DEC-0023 V4 note 3 —
 * `wiki/plans/PLN-0004/execution/mid_project_review_rulings.md` — for
 * advisory modes only; WK-0125): for `implement`, the `kb-dispatch-
 * recovery.v1` block is diagnostic evidence ONLY — an absent or malformed
 * block never changes this ladder's verdict, because delivery authority is
 * the scope-checked commit (unchanged by DEC-0037 — implement mode gets
 * constrained decoding at the pipeline layer instead, which makes the block
 * more reliably parseable without touching this ladder). For
 * `code_review`/`redteam`, the block is now opportunistic, not the
 * deliverable: a valid block drives mechanical merge gating (`delivered`,
 * `delivery_method: structured`); an absent or invalid block falls back to
 * prose (`delivered`, `delivery_method: prose_fallback`) instead of the old
 * hard `failed`/`missing_review_artifact` — the review's prose is the
 * deliverable when the structured shortcut isn't available, never a
 * discarded artifact.
 *
 * Ladder:
 *   1. Delivery-gate refusals (out-of-scope / secret-in-diff) -> `refused`.
 *   2. Delivery-gate errors (conflict / git error) -> `failed`.
 *   3. Mode-specific deliverable check:
 *      - implement: an in-scope diff landed on the branch -> `delivered`;
 *        an idempotent redelivery (`no_changes` — the exact same tree is
 *        already on the branch from the same base) -> also `delivered`;
 *        an empty delta (`no_delta` — the worker's tree matches the base
 *        tree, so no branch was ever created) -> `failed` (`no_deliverable`
 *        — DEC-0010's "silence plus no deliverable is failure, never
 *        success"). `recoveryEvidence` is never consulted in this branch.
 *      - code_review: a valid block -> `delivered` (`delivery_method:
 *        structured`, no reason); an invalid/absent block -> `delivered`,
 *        reason `prose_fallback` (`delivery_method: prose_fallback`,
 *        DEC-0037) — the chat transcript (`## Worker Report`) is the
 *        deliverable in that case.
 *      - redteam: same block-validity fallback as code_review, but a
 *        crashed/errored worker process (`piResult.outcome` `failed`/
 *        `error`) still fails with reason `process_error` regardless of
 *        block validity — checked FIRST and dominant, so prose fallback
 *        only ever covers a malformed/absent BLOCK from a process that
 *        otherwise ran, never a process that produced no real output at
 *        all (DEC-0010: no worker-authored content can manufacture a
 *        success verdict).
 *      - research: no deliverable block exists for this mode (prose-only,
 *        ruling 1 item 1) — the transcript IS the product (`## Worker
 *        Report`); `delivered` here claims only "the process ran to
 *        completion", never findings quality. A crashed/errored process
 *        still fails.
 */
function deriveVerdict(
  delivery: DeliveryOutcome,
  handoffMode: string,
  piResult?: CaptureOpts['piResult'],
  recoveryEvidence?: RecoveryBlockEvidence,
): VerdictResult {
  if (delivery.status === 'refused_out_of_scope' || delivery.status === 'secret_in_diff') {
    return { outcome: 'refused', reason: delivery.status };
  }
  if (delivery.status === 'conflict') {
    return { outcome: 'failed', reason: 'delivery_conflict' };
  }
  if (delivery.status === 'error') {
    return { outcome: 'failed', reason: 'delivery_error' };
  }
  if (handoffMode === 'implement') {
    if (delivery.status === 'delivered') return { outcome: 'delivered' };
    if (delivery.status === 'no_changes') return { outcome: 'delivered' }; // F1: idempotent redelivery
    if (delivery.status === 'no_delta') return { outcome: 'failed', reason: 'no_deliverable' }; // F2: empty delta
  }
  if (handoffMode === 'code_review') {
    // DEC-0037 (reverses DEC-0023 V4 note 3 for advisory modes; WK-0125):
    // the block is opportunistic, not the deliverable — never hard-fail a
    // genuine review over a JSON shape mismatch.
    if (!recoveryEvidence?.valid) {
      return { outcome: 'delivered', reason: 'prose_fallback', deliveryMethod: 'prose_fallback' };
    }
    return { outcome: 'delivered', deliveryMethod: 'structured' };
  }
  if (handoffMode === 'redteam') {
    // Crash detection is UNCHANGED and dominant (checked before the block-
    // validity fallback) — see the ladder doc comment above.
    if (piResult?.outcome === 'failed' || piResult?.outcome === 'error') {
      return { outcome: 'failed', reason: 'process_error' };
    }
    if (!recoveryEvidence?.valid) {
      return { outcome: 'delivered', reason: 'prose_fallback', deliveryMethod: 'prose_fallback' };
    }
    return { outcome: 'delivered', deliveryMethod: 'structured' };
  }
  if (handoffMode === 'research') {
    if (piResult?.outcome === 'failed' || piResult?.outcome === 'error') {
      return { outcome: 'failed', reason: 'process_error' };
    }
    return { outcome: 'delivered' };
  }
  return { outcome: 'failed', reason: 'unknown_mode' };
}

function describeOutcome(delivery: DeliveryOutcome): string {
  switch (delivery.status) {
    case 'delivered': {
      const base = `Delivered to \`${delivery.branch}\` at commit \`${delivery.commitSha}\`.`;
      if (delivery.ignoredFiles && delivery.ignoredFiles.length > 0) {
        return `${base} Note: ${delivery.ignoredFiles.length} gitignored file(s) under write_scope were skipped: ${delivery.ignoredFiles.join(', ')}.`;
      }
      return base;
    }
    case 'no_changes':
      return 'No changes were delivered (either the worker made none, or this is an idempotent redelivery already landed on the branch).';
    case 'no_delta':
      if (delivery.ignoredFiles && delivery.ignoredFiles.length > 0) {
        return `No changes: worker wrote only gitignored paths (${delivery.ignoredFiles.join(', ')}); delivery's "git add -A" cannot capture them.`;
      }
      return 'No changes: the worker produced no diff from the base tree. No branch was created.';
    case 'refused_out_of_scope':
      return `Refused: changes touched paths outside the declared write_scope (${delivery.offendingPaths.join(', ')}). Diff quarantined at \`${delivery.quarantinePath}\`.`;
    case 'secret_in_diff':
      return `Refused: the diff matched secret pattern(s) (${delivery.patterns.join(', ')}). Diff quarantined at \`${delivery.quarantinePath}\`.`;
    case 'conflict':
      return `Delivery conflict: the branch already carries a different tree from the same base (existing tree \`${delivery.existingTree}\`, new tree \`${delivery.newTree}\`). Nothing was landed.`;
    case 'error':
      return `Delivery error: ${delivery.message}`;
    default: {
      const exhaustiveCheck: never = delivery;
      return exhaustiveCheck;
    }
  }
}

function formatChangedFilesSection(delivery: DeliveryOutcome): string {
  const files = delivery.status === 'delivered' ? delivery.changedFiles : [];
  if (files.length === 0) return '(none)';
  return files.map((file) => `- ${file}`).join('\n');
}

function formatUsageSection(piResult: CaptureOpts['piResult'], billing?: 'seat' | 'api'): string {
  if (!piResult) return '- Tokens: unavailable\n- Cost: unavailable';
  const cost = billing === 'seat' ? 0 : piResult.usage.costUsd;
  return `- Tokens: ${piResult.usage.totalTokens}\n- Cost: $${cost}`;
}

/**
 * Render the `## Worker Report` section body (DEC-0010 diagnosis channel):
 * the worker's final assistant message, embedded VERBATIM as evidence —
 * never parsed, never consulted by `deriveVerdict` above. Absent/empty text
 * (no final message captured at all, e.g. a crashed or empty event stream)
 * renders an explicit placeholder rather than a blank section.
 */
function formatWorkerReportSection(lastAssistantText: string | undefined): string {
  return lastAssistantText && lastAssistantText.length > 0 ? lastAssistantText : '(no final message captured)';
}

/**
 * Render the `## Recovery Signal` section (D1 ruling 1; V4 note 3) from the
 * `kb-dispatch-recovery.v1` evidence extracted from the worker/reviewer/
 * redteam's terminal output block. An absent/invalid block renders a
 * `**Parse failed:**` notice instead of a table, listing every diagnostic
 * `extractRecoveryBlock`/`validateRecoveryPayload` collected — this keeps a
 * missing section from reading as silent success. This rendering is always
 * diagnostic-only from `writeResponseDoc`'s point of view; whether it also
 * drives the run's verdict is `deriveVerdict`'s call (V4 note 3 role
 * asymmetry), not this function's.
 */
function formatRecoveryBlockSection(evidence: RecoveryBlockEvidence): string[] {
  const lines: string[] = ['## Recovery Signal', ''];

  if (!evidence.valid || !evidence.result) {
    const detail = evidence.diagnostics
      .map((d) => `${d.code}: ${d.message}${d.path ? ` (${d.path})` : ''}`)
      .join('; ');
    lines.push(`**Parse failed:** ${detail || 'no diagnostics recorded'}`, '');
    return lines;
  }

  const payload: RecoveryBlockPayload = evidence.result;
  lines.push(`**Reported outcome:** ${payload.reported_outcome}`);
  if (payload.kind) {
    lines.push(`**Kind:** ${payload.kind}`);
  }
  if (payload.summary) {
    lines.push('', payload.summary);
  }

  if (payload.findings.length > 0) {
    lines.push('', '### Findings', '| ID | Severity | Blocking | Title |', '|----|----------|----------|-------|');
    for (const finding of payload.findings) {
      lines.push(`| ${finding.id} | ${finding.severity} | ${finding.blocking ? 'yes' : 'no'} | ${finding.title} |`);
    }
  }

  if (payload.reviewed_controls.length > 0) {
    lines.push('', '### Reviewed Controls', '| Control | Result |', '|---------|--------|');
    for (const control of payload.reviewed_controls) {
      lines.push(`| ${control.control_id} | ${control.result} |`);
    }
  }

  lines.push('');
  return lines;
}

/**
 * Render the `## Mount Writes` section (WK-0164) — a per-mount subsection
 * (mount path as heading) listing the relative file paths the host-side walk
 * found newer than run start. Returns an empty array (nothing rendered) when
 * `mountWrites` is absent/empty.
 */
function formatMountWritesSection(mountWrites: CaptureOpts['mountWrites']): string[] {
  if (!mountWrites || mountWrites.length === 0) return [];
  const lines: string[] = ['## Mount Writes', ''];
  for (const mount of mountWrites) {
    lines.push(`### ${mount.mountPath}`, '');
    if (mount.files.length === 0) {
      lines.push('(none)');
    } else {
      lines.push(...mount.files.map((file) => `- ${file}`));
    }
    lines.push('');
  }
  return lines;
}

/**
 * Serialize a `BackendFingerprint` for the `backend_fingerprint` provenance
 * field. host/model are written even when `serverVersion` is null (no
 * version endpoint for this backend kind, or the probe failed) — losing
 * host/model just because the version half is unprobeable throws away real
 * signal (this was the bug: the caller used to narrow to `serverVersion`
 * alone and drop the whole fingerprint whenever it was null).
 */
function formatBackendFingerprint(fingerprint: BackendFingerprint): string {
  return `${fingerprint.host}|${fingerprint.model}|${fingerprint.serverVersion ?? 'unknown'}`;
}

/**
 * Build the `HO-XXXX.response.md` content and write it into the run dir.
 * Structured frontmatter header (outcome/model/isolation/usage/branch/changed
 * files) followed by a free-form findings body (spec §5).
 */
export async function writeResponseDoc(opts: CaptureOpts): Promise<DispatchResult<CaptureResult>> {
  const { runDir, handoff, delivery, piResult, model, isolationBackend } = opts;

  const verdict = deriveVerdict(delivery, handoff.mode, piResult, opts.recoveryEvidence);
  const branch = deriveBranch(handoff.id, delivery);
  const changedFiles = delivery.status === 'delivered' ? delivery.changedFiles : [];
  const totalTokens = piResult?.usage.totalTokens ?? 0;
  const costUsd = opts.billing === 'seat' ? 0 : (piResult?.usage.costUsd ?? 0);
  const changedFilesYaml = `[${changedFiles.map((file) => JSON.stringify(file)).join(', ')}]`;
  const credentialsGrantedYaml = `[${(opts.credentialsGranted ?? []).map((name) => JSON.stringify(name)).join(', ')}]`;

  const frontmatterLines = [
    '---',
    `handoff_id: ${handoff.id}`,
    `outcome: ${verdict.outcome}`,
    `model: ${model ?? ''}`,
    `isolation_backend: ${isolationBackend ?? ''}`,
    `total_tokens: ${totalTokens}`,
    `cost_usd: ${costUsd}`,
    `branch: ${branch}`,
    `changed_files: ${changedFilesYaml}`,
    `credentials_granted: ${credentialsGrantedYaml}`,
    `effort_requested: ${opts.effort ?? ''}`,
  ];
  if (opts.compaction && opts.compaction.total > 0) {
    frontmatterLines.push(`compaction_total: ${opts.compaction.total}`);
    frontmatterLines.push(`compaction_succeeded: ${opts.compaction.succeeded}`);
    frontmatterLines.push(`compaction_failed: ${opts.compaction.failed}`);
  }
  if (verdict.reason) frontmatterLines.push(`reason: ${verdict.reason}`);
  // WK-0125/DEC-0037: observability for the code_review/redteam
  // structured-vs-prose-fallback fork (never set for implement/research).
  if (verdict.deliveryMethod) frontmatterLines.push(`delivery_method: ${verdict.deliveryMethod}`);
  // Resolved-value provenance (S3 ruling 8): stamped only when the caller has
  // them (e.g. never for the delivery-gate refusal callers, which pass no
  // model/backend at all) — RESOLVED runtime values only, never a template.
  if (opts.baseUrl) frontmatterLines.push(`base_url: ${opts.baseUrl}`);
  if (opts.backend) frontmatterLines.push(`backend: ${opts.backend}`);
  if (opts.piVersion) frontmatterLines.push(`pi_version: ${opts.piVersion}`);
  if (opts.backendFingerprint) frontmatterLines.push(`backend_fingerprint: ${formatBackendFingerprint(opts.backendFingerprint)}`);
  if (opts.wikiCommit) frontmatterLines.push(`wiki_commit: ${opts.wikiCommit}`);
  if (opts.inferenceProvider) frontmatterLines.push(`inference_provider: ${opts.inferenceProvider}`);
  // WK-0166: stamp the recovery evidence merge-delivery needs so it can read
  // frontmatter instead of re-parsing the rendered `## Worker Report` markdown
  // (the regex it used to run stopped at the FIRST `\n## `, which is the
  // worker's own heading when its report starts with one — see WK-0166).
  const recoveryOutcome =
    opts.recoveryEvidence?.valid && opts.recoveryEvidence.result ? opts.recoveryEvidence.result.reported_outcome : '';
  const recoveryValid = opts.recoveryEvidence?.valid ?? false;
  const workerReportChars = (opts.lastAssistantText?.trim() ?? '').length;
  frontmatterLines.push(`recovery_outcome: ${recoveryOutcome}`);
  frontmatterLines.push(`recovery_valid: ${recoveryValid}`);
  frontmatterLines.push(`worker_report_chars: ${workerReportChars}`);
  frontmatterLines.push('---', '');
  const frontmatter = frontmatterLines.join('\n');

  const bodyLines = [
    `# Response: ${handoff.title}`,
    '',
    '## Outcome',
    describeOutcome(delivery),
    '',
    '## Changed Files',
    formatChangedFilesSection(delivery),
    '',
    '## Usage',
    formatUsageSection(piResult, opts.billing),
    '',
    ...formatTokenDetailSection(piResult?.usage, opts.modelId, opts.billing),
    '## Worker Report (evidence, not verdict)',
    '',
    formatWorkerReportSection(opts.lastAssistantText),
    '',
  ];
  if (opts.compaction && opts.compaction.total > 0) {
    bodyLines.push(
      '## Compaction',
      `${opts.compaction.total} compaction events: ${opts.compaction.succeeded} succeeded, ${opts.compaction.failed} failed.`,
      '',
    );
  }
  if (opts.mountWrites && opts.mountWrites.length > 0) {
    bodyLines.push(...formatMountWritesSection(opts.mountWrites));
  }
  if (opts.recoveryEvidence) {
    bodyLines.push(...formatRecoveryBlockSection(opts.recoveryEvidence));
  }
  const body = bodyLines.join('\n');

  const responseContent = `${frontmatter}\n${body}`;
  const responsePath = join(runDir, `${handoff.id}.response.md`);

  try {
    await writeFile(responsePath, responseContent, 'utf8');
  } catch (err) {
    return fail('FILE_WRITE_ERROR', `Failed to write response doc to ${responsePath}.`, err);
  }

  return ok({ responsePath, responseContent });
}

/**
 * HO frontmatter provenance fields written back after a run (spec §5's
 * "written back by dispatch after the run" block, minus `status`, which the
 * orchestrator sets separately as part of the broader lifecycle). `run_id`
 * is the run dir's basename — v1's proven convention
 * (`paths.ts`: `.../runs/<handoffId>/RUN-<uuid>/`) that v2 keeps (spec §8
 * capture: "run dirs keep today's proven layout"). `credentials_granted`
 * (S3 T10) is the caller-supplied list of granted profile names — names
 * only, never values — defaulting to `[]` when the caller doesn't pass one
 * (e.g. no credentials were requested).
 */
export function buildProvenanceWriteBack(opts: CaptureOpts): ProvenanceWriteBack {
  const { runDir, handoff, delivery, model, family, isolationBackend } = opts;

  const fields: Record<string, string | boolean | string[]> = {
    run_id: basename(runDir),
    // WK-0136: reflect the actual resolved family when the caller has it
    // (pipeline.ts threads `model.family`); fall back to the model string
    // rather than the old hardcoded 'pi' when family is unavailable.
    agent: family ?? model ?? '',
    model: model ?? '',
    enforced: true,
    isolation_backend: isolationBackend ?? '',
    branch: deriveBranch(handoff.id, delivery),
    response: `${handoff.id}.response.md`,
    credentials_granted: opts.credentialsGranted ?? [],
  };

  // Resolved-value provenance (S3 ruling 8) — same RESOLVED-only invariant as
  // writeResponseDoc above; present only when the caller supplied them.
  if (opts.baseUrl) fields.base_url = opts.baseUrl;
  if (opts.backend) fields.backend = opts.backend;
  if (opts.piVersion) fields.pi_version = opts.piVersion;
  if (opts.backendFingerprint) fields.backend_fingerprint = formatBackendFingerprint(opts.backendFingerprint);
  if (opts.wikiCommit) fields.wiki_commit = opts.wikiCommit;
  if (opts.inferenceProvider) fields.inference_provider = opts.inferenceProvider;
  if (opts.compaction && opts.compaction.total > 0) {
    fields.compaction_total = String(opts.compaction.total);
    fields.compaction_succeeded = String(opts.compaction.succeeded);
    fields.compaction_failed = String(opts.compaction.failed);
  }

  return { fields };
}

/**
 * Pi coding-agent adapter (WK-0073 pick; T4 S0). Facts-only (spec D10 / §8 adapter
 * interface: "Adapters may not gate, decide policy, touch credentials, or build
 * shell strings elsewhere" — the launcher owns all policy). This module only
 * reports the invocation shape and parses Pi's own JSON-lines event stream; it
 * never spawns a process itself.
 *
 * Key facts baked in from the WK-0073 spike / tracker "Harness Rulings":
 * - `PI_CODING_AGENT_DIR` redirects Pi's entire per-process agent config dir —
 *   required per-worker (concurrent workers sharing `~/.pi/agent/` hit an
 *   auth.json lock, earendil-works/pi#8928).
 * - `--mode json` always exits 0, even on error — the adapter must parse the
 *   JSON-lines stream for `stopReason: "error"` on `message_end`/`turn_end`;
 *   exit code alone is not evidence of outcome.
 * - Per-turn `usage` (incl. computed `cost`) rides on every assistant
 *   `message_end` event; there is no end-of-run summary event, so usage is
 *   summed across all of them.
 * - `--approve` is required in non-interactive (`-p`) mode, else Pi silently
 *   skips project-local resources (`defaultProjectTrust: "ask"`).
 */
import type { DispatchResult } from '../errors.js';
import { ok } from '../errors.js';
import type { ModelEntry } from '../model-registry.js';

export interface PiModelsJson {
  providers: Record<
    string,
    {
      baseUrl: string;
      api: string;
      apiKey: string;
      models: Array<{
        id: string;
        contextWindow: number;
        maxTokens: number;
        cost: { input: number; output: number; cacheRead: number; cacheWrite: number };
        samplingParams?: Record<string, unknown>;
      }>;
      compat?: { supportsDeveloperRole?: boolean; supportsReasoningEffort?: boolean };
    }
  >;
}

export interface PiInvocation {
  cmd: string;
  args: string[];
  env: Record<string, string>;
  cwd: string;
  /** JSON string to write to `PI_CODING_AGENT_DIR/models.json`. */
  modelsJsonContent: string;
}

export interface PiUsage {
  totalTokens: number;
  costUsd: number;
  /**
   * Per-field split (WK-0123), summed across every assistant `message_end`
   * event exactly like `totalTokens`/`costUsd` above. `null` when the field
   * never appeared in ANY event of the stream (older captures, or a
   * provider that genuinely doesn't report it) — never a fabricated 0.
   * DEC-0009 capture-first ruling (`wiki/issues/WK-0123.md`): a real
   * captured Pi/OpenRouter stream (`tests/fixtures/pi-output-code-
   * review.jsonl`) carries this split under `usage.input/output/cacheRead/
   * cacheWrite/reasoning`, so it is parsed here rather than falling back to
   * capture.ts's bounded-range estimate, which now only triggers when these
   * fields are genuinely absent.
   */
  inputTokens: number | null;
  outputTokens: number | null;
  cacheReadTokens: number | null;
  cacheWriteTokens: number | null;
  reasoningTokens: number | null;
}

/** Compaction event statistics extracted from the Pi event stream (T33 Phase 3). */
export interface PiCompaction {
  total: number;
  succeeded: number;
  failed: number;
}

export interface PiResult {
  outcome: 'completed' | 'failed' | 'error';
  stopReason?: string;
  hasAgentEnd: boolean;
  usage: PiUsage;
  compaction: PiCompaction;
  /**
   * Concatenated `type === 'text'` content blocks from EVERY assistant
   * `message_end` event in the stream, in stream order — the worker's raw
   * response text, spanning EVERY assistant message in the run (narration,
   * tool-call commentary, and the final reply, all concatenated).
   * `thinking` and `toolCall` blocks, and non-assistant (`user`/
   * `toolResult`) `message_end`s, are excluded. `''` when the stream
   * carried no assistant `message_end` with a `text` block (e.g. the
   * empty-stream fallback). Right tool for whole-run scans (e.g. debugging
   * the full transcript); wrong tool for anything that expects to see only
   * the worker's FINAL message — see `lastAssistantText` below.
   *
   * WK-0092/WK-0093: extracted from `message_end.message.content` blocks —
   * Pi assembles the complete message there; it never emits a top-level
   * `text_delta` event (deltas ride inside `message_update.
   * assistantMessageEvent`, which this adapter does not read at all). The
   * prior implementation read a top-level `text_delta` that Pi has never
   * emitted, so this field — and `lastAssistantText` — were dead code since
   * S0; verified and fixed against a real captured stream, golden fixture
   * `tests/fixtures/pi-output-code-review.jsonl`.
   */
  accumulatedText: string;
  /**
   * Text of the LAST assistant `message_end` only — concatenated
   * `type === 'text'` content blocks of that one message; narration and
   * tool-call commentary from earlier turns excluded, and `thinking` /
   * `toolCall` blocks within that same message also excluded. `''` when the
   * stream carried no assistant `message_end` at all, or when the last one
   * had no `text` block (e.g. a final turn that was pure tool calls).
   *
   * No partial-text recovery is attempted for a stream truncated
   * mid-message (no closing `message_end` for the in-flight final turn) —
   * WK-0092 accepted trade-off: such streams are already classified
   * `failed`/`truncated_stream`, and the delta-based recovery this replaces
   * never actually worked (Pi never emits the top-level event it read), so
   * nothing real is lost by not reconstructing one.
   *
   * The `kb-dispatch-recovery.v1` terminal-block extractor
   * (`recovery-block.ts`'s `extractRecoveryBlock`) reads from THIS field,
   * not `accumulatedText` — an agentic worker narrates and calls tools
   * before producing its terminal fenced block, so the whole-session text
   * may contain multiple JSON-shaped blocks. The recovery block is always
   * in the worker's final message, regardless of how many turns the worker
   * takes or which model/backend/tier served it, so isolating that one
   * message here (in the one place that already walks the event stream,
   * D10 facts-only) fixes the data flow for every caller — widening the
   * extractor's scan window instead would only paper over this one symptom, and
   * would make a markdown `---` horizontal rule in the narration
   * ambiguous with the real header delimiter.
   */
  lastAssistantText: string;
}

// New v2 error code produced by this module; will be merged into the shared
// DispatchErrorCode union in errors.ts at wave-3 integration. errors.ts is not
// modified by this file (wave-1 constraint).
type AdapterErrorCode = 'ADAPTER_FAILED';

function fail<T = never>(message: string, detail?: unknown): DispatchResult<T> {
  return { ok: false, error: 'ADAPTER_FAILED' as AdapterErrorCode, message, detail } as unknown as DispatchResult<T>;
}

/**
 * Build Pi's `models.json` config shape for a single registry entry. `apiKey`
 * uses Pi's `$VAR` interpolation syntax when the model declares an env var
 * (the actual secret value is sourced from secrets.env at spawn time, never
 * here); models with no secret (e.g. local Ollama) get a literal placeholder.
 */
export function buildModelsJson(model: ModelEntry, requestParams?: Record<string, unknown>): PiModelsJson {
  const apiKey = model.apiKeyEnv ? `$${model.apiKeyEnv}` : 'placeholder';

  return {
    providers: {
      [model.provider]: {
        baseUrl: model.baseUrl,
        api: model.api,
        apiKey,
        models: [
          {
            id: model.modelId,
            contextWindow: model.contextWindow,
            maxTokens: model.maxTokens,
            cost: { ...model.cost },
            ...(requestParams ? { samplingParams: requestParams } : {}),
          },
        ],
        ...(model.compat ? { compat: { ...model.compat } } : {}),
      },
    },
  };
}

/**
 * Build the Pi invocation shape (argv + env + cwd) for a single run. Facts only —
 * this does not spawn anything; the launcher (Wave 3 pipeline.ts) does.
 */
export function buildInvocation(
  promptFilePath: string,
  model: ModelEntry,
  clonePath: string,
  workerDir: string,
): PiInvocation {
  const env: Record<string, string> = { PI_CODING_AGENT_DIR: workerDir, PI_OFFLINE: '1' };
  if (model.apiKeyEnv) {
    // Placeholder reference only — the real value is sourced from secrets.env at
    // spawn time (execution/s0-rulings.md ruling 5), never assembled here.
    env[model.apiKeyEnv] = `$${model.apiKeyEnv}`;
  }

  return {
    cmd: 'pi',
    args: [
      '-p',
      '--mode',
      'json',
      '--model',
      `${model.provider}/${model.modelId}`,
      '--no-session',
      '--approve',
      '--',
      `@${promptFilePath}`,
    ],
    env,
    cwd: clonePath,
    modelsJsonContent: JSON.stringify(buildModelsJson(model)),
  };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

/**
 * Extract the concatenated `type === 'text'` content blocks of one assistant
 * `message_end`'s `message.content` array — `thinking` and `toolCall` blocks
 * are deliberately skipped (WK-0092/WK-0093: verified against a real
 * captured `pi-output.log`; the golden fixture is
 * `tests/fixtures/pi-output-code-review.jsonl`). Returns `''` when `content`
 * is missing or not an array — defensive, since some hand-rolled
 * usage/error-path test fixtures (and edge-case Pi events) carry a
 * `message` with no `content` at all.
 */
function extractAssistantMessageText(message: Record<string, unknown>): string {
  if (!Array.isArray(message.content)) return '';
  let text = '';
  for (const block of message.content) {
    if (isRecord(block) && block.type === 'text' && typeof block.text === 'string') {
      text += block.text;
    }
  }
  return text;
}

/**
 * Parse Pi's JSON-lines stdout. Non-JSON lines are skipped (Pi's `--mode json`
 * output is pure JSON-lines, but the adapter tolerates stray banner/log lines
 * rather than failing the whole run over one bad line). Returns ADAPTER_FAILED
 * only when the stream has content but none of it parses as JSON at all.
 */
export function parsePiOutput(stdout: string): DispatchResult<PiResult> {
  const lines = stdout
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line.length > 0);

  let parsedCount = 0;
  let totalTokens = 0;
  let costUsd = 0;
  let inputTokens = 0;
  let outputTokens = 0;
  let cacheReadTokens = 0;
  let cacheWriteTokens = 0;
  let reasoningTokens = 0;
  let sawInputTokens = false;
  let sawOutputTokens = false;
  let sawCacheReadTokens = false;
  let sawCacheWriteTokens = false;
  let sawReasoningTokens = false;
  let sawError = false;
  let stopReason: string | undefined;
  let accumulatedText = '';
  let lastAssistantText = '';
  let hasAgentEnd = false;
  let allAttemptsErrored = false;
  let compactionTotal = 0;
  let compactionSucceeded = 0;
  let compactionFailed = 0;

  for (const line of lines) {
    let event: unknown;
    try {
      event = JSON.parse(line);
    } catch {
      // Skip non-JSON lines (stray banners, etc.) — facts-only parsing tolerates them.
      continue;
    }
    parsedCount++;

    if (!isRecord(event)) continue;
    const type = event.type;

    if (type === 'message_end' || type === 'turn_end') {
      if (event.stopReason === 'error') {
        sawError = true;
        stopReason = 'error';
      } else if (typeof event.stopReason === 'string' && stopReason === undefined) {
        stopReason = event.stopReason;
      }
    }

    if (type === 'message_end' && isRecord(event.message) && event.message.role === 'assistant') {
      const usage = event.message.usage;
      if (isRecord(usage)) {
        if (typeof usage.totalTokens === 'number') {
          totalTokens += usage.totalTokens;
        }
        if (isRecord(usage.cost) && typeof usage.cost.total === 'number') {
          costUsd += usage.cost.total;
        }
        // WK-0123 (DEC-0009 capture-first ruling): real captured
        // Pi/OpenRouter streams carry this split under `usage.input/output/
        // cacheRead/cacheWrite/reasoning` — verified against
        // tests/fixtures/pi-output-code-review.jsonl.
        if (typeof usage.input === 'number') {
          inputTokens += usage.input;
          sawInputTokens = true;
        }
        if (typeof usage.output === 'number') {
          outputTokens += usage.output;
          sawOutputTokens = true;
        }
        if (typeof usage.cacheRead === 'number') {
          cacheReadTokens += usage.cacheRead;
          sawCacheReadTokens = true;
        }
        if (typeof usage.cacheWrite === 'number') {
          cacheWriteTokens += usage.cacheWrite;
          sawCacheWriteTokens = true;
        }
        if (typeof usage.reasoning === 'number') {
          reasoningTokens += usage.reasoning;
          sawReasoningTokens = true;
        }
      }
      // WK-0092/WK-0093: text rides on the assembled `content` array of the
      // assistant message_end, not a top-level `text_delta` event (Pi never
      // emits one). Overwritten on every assistant message_end, so after the
      // loop this holds the LAST one — see `lastAssistantText`'s doc comment.
      const messageText = extractAssistantMessageText(event.message);
      accumulatedText += messageText;
      lastAssistantText = messageText;
    }

    if (type === 'agent_end') {
      hasAgentEnd = true;
    }

    if (type === 'auto_retry_end' && event.success === false) {
      allAttemptsErrored = true;
    }

    if (type === 'compaction_end') {
      compactionTotal++;
      const hasResult = isRecord(event) && event.result !== undefined && event.result !== null;
      const notAborted = isRecord(event) && event.aborted === false;
      if (hasResult && notAborted) {
        compactionSucceeded++;
      } else {
        compactionFailed++;
      }
    }
  }

  if (lines.length > 0 && parsedCount === 0) {
    return fail('No parseable JSON-lines events found in Pi output.', { rawLineCount: lines.length });
  }

  if (parsedCount === 0) {
    return ok({
      outcome: 'failed',
      stopReason: 'empty_stream',
      hasAgentEnd: false,
      usage: {
        totalTokens: 0,
        costUsd: 0,
        inputTokens: null,
        outputTokens: null,
        cacheReadTokens: null,
        cacheWriteTokens: null,
        reasoningTokens: null,
      },
      compaction: { total: compactionTotal, succeeded: compactionSucceeded, failed: compactionFailed },
      accumulatedText: '',
      lastAssistantText: '',
    });
  }

  // Facts-only: the launcher (not this adapter) owns outcome policy beyond
  // error-detection. `agent_end` presence with no observed error defaults to
  // 'completed'. Post-DEC-0010, the response-doc-level verdict is computed
  // mechanically by capture.ts from delivery-gate facts and per-mode
  // deliverable checks, never from the worker's response text — that text
  // is embedded verbatim as evidence only (`## Worker Report`).
  const outcome: PiResult['outcome'] = allAttemptsErrored
    ? 'failed'
    : sawError
      ? 'error'
      : hasAgentEnd
        ? 'completed'
        : 'failed';
  if (allAttemptsErrored) {
    stopReason = 'all_attempts_errored';
  } else if (outcome === 'failed' && stopReason === undefined) {
    stopReason = 'truncated_stream';
  }

  return ok({
    outcome,
    stopReason,
    hasAgentEnd,
    usage: {
      totalTokens,
      costUsd,
      inputTokens: sawInputTokens ? inputTokens : null,
      outputTokens: sawOutputTokens ? outputTokens : null,
      cacheReadTokens: sawCacheReadTokens ? cacheReadTokens : null,
      cacheWriteTokens: sawCacheWriteTokens ? cacheWriteTokens : null,
      reasoningTokens: sawReasoningTokens ? reasoningTokens : null,
    },
    compaction: { total: compactionTotal, succeeded: compactionSucceeded, failed: compactionFailed },
    accumulatedText,
    lastAssistantText,
  });
}

/**
 * WK-0153 — unhandled-runs reminder core query.
 *
 * Computes the list of finished-but-unhandled dispatch runs so callers (MCP
 * responses, CLI banners — wired up separately) can remind the operator of
 * completions they haven't acted on yet. Scans `.agent-runs/runs/` with the
 * same dual v1/v2 layout `status.ts` and `cleanup.ts` already read:
 *   - v2: `<runDir>/state.json` (schema_version 2, `completed_at` on the run root)
 *   - v1 (legacy): `<runDir>/metadata/meta.json` (`status` + `completed_at`;
 *     the v1 controller that wrote these was retired in WK-0134 — only
 *     historical run dirs use this path today)
 *
 * "Handled" is derived entirely from existing disk state (D2 ruling,
 * WK-0153): a review HO's `reviewed_run` stamp, or the run dir simply being
 * gone (cleanup). No new bookkeeping, no caching — every call re-scans.
 */
import { readFile, readdir } from 'node:fs/promises';
import { join } from 'node:path';

import type { DispatchResult } from './errors.js';
import { ok, fail } from './errors.js';

export interface UnhandledRun {
  handoff_id: string;
  run_id: string;
  status: string;
  branch: string;
  completed_at: string;
  note?: string;
}

/** Union of v2's and legacy v1's terminal status vocabularies (dispatch-controller-entry.ts's `V2RunStatus`; v1's `TerminalRunStatus` used `completed` where v2 uses `delivered`). Mirrors derive-review.ts's identical set. */
const V2_TERMINAL = new Set(['delivered', 'completed', 'failed', 'refused', 'timed_out', 'cancelled']);

/** Only these terminal outcomes can be discharged by review evidence — the rest nag until their run dir is cleaned up. */
const DISCHARGEABLE_BY_REVIEW = new Set(['delivered', 'completed']);

interface RunState {
  runId: string;
  status: string;
  completedAt: string;
  branch: string;
  unreadable: boolean;
  note?: string;
}

interface ReviewEvidenceEntry {
  reviewedRunId: string;
}

/**
 * Scan `wiki/handoffs/` for `code_review` HOs and index each one's discharge
 * evidence (`base_ref: dispatch/<handoff_id>` + `reviewed_run: <run id>`) by
 * the handoff id it targets. A review HO with no `reviewed_run` stamp (e.g.
 * one derived before this feature existed) contributes no evidence — it
 * discharges nothing (WK-0153 D2: "legacy review HOs without reviewed_run
 * discharge nothing").
 *
 * Deliberately a lightweight regex frontmatter read rather than `ho.ts`'s
 * `parseHandoff` — that parser requires a full HO record (title, write_scope,
 * non-empty acceptance/validation) and would reject a well-formed review HO
 * that happens to omit one of those, coupling this read to record shape it
 * doesn't need. Only `mode`, `base_ref`, and `reviewed_run` matter here.
 */
async function loadReviewEvidence(repoRoot: string): Promise<Map<string, ReviewEvidenceEntry>> {
  const evidence = new Map<string, ReviewEvidenceEntry>();
  const handoffsDir = join(repoRoot, 'wiki', 'handoffs');

  let files: string[];
  try {
    files = await readdir(handoffsDir);
  } catch {
    return evidence;
  }

  for (const file of files) {
    if (!file.startsWith('HO-') || !file.endsWith('.md') || file.endsWith('.response.md')) {
      continue;
    }

    try {
      const content = await readFile(join(handoffsDir, file), 'utf-8');
      const fmMatch = content.match(/^---\n([\s\S]*?)\n---/);
      if (!fmMatch) continue;
      const fm = fmMatch[1] ?? '';

      const modeMatch = fm.match(/^mode:\s*(.+)$/m);
      if (!modeMatch || modeMatch[1].trim() !== 'code_review') continue;

      const baseRefMatch = fm.match(/^base_ref:\s*"?([^"\n]+)"?$/m);
      if (!baseRefMatch) continue;

      const baseRef = baseRefMatch[1].trim();
      const hoMatch = baseRef.match(/^dispatch\/(HO-\d+)$/);
      if (!hoMatch) continue;
      const targetHandoffId = hoMatch[1];

      const reviewedRunMatch = fm.match(/^reviewed_run:\s*"?([^"\n]+)"?$/m);
      if (!reviewedRunMatch) continue;
      const reviewedRunId = reviewedRunMatch[1].trim();

      if (targetHandoffId) {
        evidence.set(targetHandoffId, { reviewedRunId });
      }
    } catch {
      // Skip unreadable handoff files.
    }
  }

  return evidence;
}

/** Read a single run dir's status/completed_at/branch, trying v2's root `state.json` then falling back to v1's `metadata/meta.json`. Never throws — an unreadable run dir is reported via the `unreadable` flag, not an exception. */
async function readRunState(runDir: string): Promise<Omit<RunState, 'runId'>> {
  let status = '';
  let completedAt = '';
  let branch = '';
  let unreadable = false;
  let note: string | undefined;

  try {
    const raw = await readFile(join(runDir, 'state.json'), 'utf-8');
    const state = JSON.parse(raw) as Record<string, unknown>;
    if (state.schema_version === 2) {
      status = typeof state.status === 'string' ? state.status : '';
      completedAt = typeof state.completed_at === 'string' ? state.completed_at : '';
      branch = typeof state.branch === 'string' ? state.branch : '';
    } else {
      throw new Error('not v2');
    }
  } catch {
    try {
      const raw = await readFile(join(runDir, 'metadata', 'meta.json'), 'utf-8');
      const meta = JSON.parse(raw) as Record<string, unknown>;
      status = typeof meta.status === 'string' ? meta.status : '';
      completedAt = typeof meta.completed_at === 'string' ? meta.completed_at : '';
    } catch {
      unreadable = true;
      note = `state.json and metadata/meta.json both unreadable in ${runDir}`;
    }
  }

  return { status, completedAt, branch, unreadable, note };
}

export async function listUnhandledRuns(repoRoot: string): Promise<DispatchResult<UnhandledRun[]>> {
  try {
    const runsDir = join(repoRoot, '.agent-runs', 'runs');
    let handoffDirs: string[];
    try {
      handoffDirs = await readdir(runsDir);
    } catch {
      return ok([]);
    }

    const handoffRuns = new Map<string, RunState[]>();

    for (const handoffId of handoffDirs) {
      let runIds: string[];
      try {
        runIds = await readdir(join(runsDir, handoffId));
      } catch {
        continue;
      }

      const runs: RunState[] = [];
      for (const runId of runIds) {
        const runDir = join(runsDir, handoffId, runId);
        const state = await readRunState(runDir);
        // All runs of an HO share one delivery branch (WK-0153) — default to
        // it when the run's own record carries none (v1 runs, or a v2
        // no-op/failed outcome that never created a branch).
        const branch = state.branch || `dispatch/${handoffId}`;
        runs.push({ ...state, runId, branch });
      }

      if (runs.length > 0) {
        handoffRuns.set(handoffId, runs);
      }
    }

    const reviewEvidence = await loadReviewEvidence(repoRoot);

    const unhandled: UnhandledRun[] = [];

    for (const [handoffId, runs] of handoffRuns) {
      // An in-flight retry of the same HO suppresses its terminal sibling's
      // line (WK-0153 D2 concurrency note) — it is already visible via
      // `status`, and "latest terminal run" moves automatically once the
      // retry itself reaches a terminal state.
      const hasNonTerminal = runs.some((r) => !r.unreadable && !V2_TERMINAL.has(r.status) && r.status !== '');

      const terminalRuns = runs.filter((r) => !r.unreadable && V2_TERMINAL.has(r.status));
      terminalRuns.sort((a, b) => {
        const cmp = b.completedAt.localeCompare(a.completedAt);
        return cmp !== 0 ? cmp : b.runId.localeCompare(a.runId);
      });
      const latestTerminal = terminalRuns[0];

      // Unreadable run dirs are always surfaced, regardless of what else is
      // happening for this HO — fail loud, never silently skipped.
      for (const ur of runs.filter((r) => r.unreadable)) {
        unhandled.push({
          handoff_id: handoffId,
          run_id: ur.runId,
          status: 'unreadable',
          branch: `dispatch/${handoffId}`,
          completed_at: '',
          note: ur.note,
        });
      }

      if (!latestTerminal) continue;
      if (hasNonTerminal) continue;

      if (DISCHARGEABLE_BY_REVIEW.has(latestTerminal.status)) {
        const evidence = reviewEvidence.get(handoffId);
        if (evidence && evidence.reviewedRunId === latestTerminal.runId) {
          continue; // Discharged by a matching review HO.
        }
      }
      // failed/refused/cancelled/timed_out: never discharged by review —
      // only cleanup removing the run dir clears these.

      unhandled.push({
        handoff_id: handoffId,
        run_id: latestTerminal.runId,
        status: latestTerminal.status,
        branch: latestTerminal.branch,
        completed_at: latestTerminal.completedAt,
      });
    }

    return ok(unhandled);
  } catch (err) {
    return fail('STATUS_ERROR', 'Failed to list unhandled runs.', err);
  }
}

import { readFile, readdir, rm, stat } from 'node:fs/promises';
import { join } from 'node:path';

import type { CleanupOpts, CleanupReport } from './types.js';
import type { DispatchResult } from './errors.js';
import { ok, fail } from './errors.js';

const DEFAULT_MAX_AGE_DAYS = 7;

async function listReviewDirs(repoRoot: string): Promise<string[]> {
  const reviewsDir = join(repoRoot, '.agent-runs', 'reviews');
  try {
    return await readdir(reviewsDir);
  } catch {
    return [];
  }
}

async function listRunDirs(repoRoot: string): Promise<{ handoffId: string; runId: string }[]> {
  const runsDir = join(repoRoot, '.agent-runs', 'runs');
  let handoffDirs: string[];
  try {
    handoffDirs = await readdir(runsDir);
  } catch {
    return [];
  }

  const runs: { handoffId: string; runId: string }[] = [];
  for (const handoffId of handoffDirs) {
    const handoffPath = join(runsDir, handoffId);
    try {
      const runIds = await readdir(handoffPath);
      for (const runId of runIds) {
        runs.push({ handoffId, runId });
      }
    } catch {
      // skip inaccessible directories
    }
  }

  return runs;
}




async function isOlderThan(path: string, maxAgeMs: number): Promise<boolean> {
  if (maxAgeMs <= 0) return true;
  try {
    const s = await stat(path);
    return Date.now() - s.mtimeMs > maxAgeMs;
  } catch {
    return false;
  }
}

// WK-0153: ordering key for sibling-run cleanup. v2 runs carry `completed_at`
// directly on the run-root `state.json` (schema_version 2); v1 runs carry it
// on `metadata/meta.json` instead (status.ts's dual-layout comment; wait.ts
// reads the same file). Falls back to the run dir's own mtime — the same
// signal `isOlderThan` above already relies on — when neither file yields a
// parseable timestamp (e.g. a still-running run with no completed_at yet).
async function getRunTimestampMs(runDir: string): Promise<number> {
  try {
    const raw = await readFile(join(runDir, 'state.json'), 'utf-8');
    const state = JSON.parse(raw) as Record<string, unknown>;
    if (state.schema_version === 2 && typeof state.completed_at === 'string') {
      const ms = Date.parse(state.completed_at);
      if (Number.isFinite(ms)) return ms;
    }
  } catch {
    // fall through to v1
  }

  try {
    const raw = await readFile(join(runDir, 'metadata', 'meta.json'), 'utf-8');
    const meta = JSON.parse(raw) as Record<string, unknown>;
    if (typeof meta.completed_at === 'string') {
      const ms = Date.parse(meta.completed_at);
      if (Number.isFinite(ms)) return ms;
    }
  } catch {
    // fall through to mtime
  }

  try {
    const s = await stat(runDir);
    return s.mtimeMs;
  } catch {
    return 0;
  }
}

export async function cleanup(opts: CleanupOpts = {}): Promise<DispatchResult<CleanupReport>> {
  const maxAgeDays = opts.maxAgeDays ?? DEFAULT_MAX_AGE_DAYS;
  const maxAgeMs = maxAgeDays * 24 * 60 * 60 * 1000;

  const report: CleanupReport = {
    orphanReviews: [],
    orphanRuns: [],
    staleTokens: [],
    expiredTokens: [],
    totalRemoved: 0,
  };

  try {
    if (opts.dir) {
      const reviewIds = await listReviewDirs(opts.dir);

      for (const reviewId of reviewIds) {
        const reviewPath = join(opts.dir, '.agent-runs', 'reviews', reviewId);
        const old = await isOlderThan(reviewPath, maxAgeMs);
        if (old) {
          await rm(reviewPath, { recursive: true, force: true });
          report.orphanReviews.push(reviewId);
          report.totalRemoved++;
        }
      }
    }

    if (opts.dir) {
      const runs = await listRunDirs(opts.dir);
      const reviewIds = await listReviewDirs(opts.dir);
      const reviewIdSet = new Set(reviewIds);

      for (const { handoffId, runId } of runs) {
        const runDir = join(opts.dir, '.agent-runs', 'runs', handoffId, runId);
        const metaPath = join(runDir, 'metadata', 'review.json');
        let isOrphan = false;

        try {
          const raw = await readFile(metaPath, 'utf-8');
          const meta = JSON.parse(raw) as { review_id?: string; reviewId?: string };
          const reviewId = meta.review_id ?? meta.reviewId;
          if (reviewId && !reviewIdSet.has(reviewId)) {
            isOrphan = true;
          }
        } catch {
          const old = await isOlderThan(runDir, maxAgeMs);
          if (old) isOrphan = true;
        }

        if (isOrphan) {
          await rm(runDir, { recursive: true, force: true });
          report.orphanRuns.push(`${handoffId}/${runId}`);
          report.totalRemoved++;
        }
      }
    }

    // WK-0153: a removed run supersedes all OLDER runs of the same HO — sweep
    // them too, so an older terminal run can't resurface as "latest" once a
    // newer one is cleaned up.
    if (opts.dir) {
      const dir = opts.dir;
      const affectedHandoffIds = new Set<string>();
      for (const entry of report.orphanRuns) {
        const handoffId = entry.split('/')[0];
        if (handoffId) affectedHandoffIds.add(handoffId);
      }

      if (affectedHandoffIds.size > 0) {
        const remainingRuns = await listRunDirs(dir);

        for (const handoffId of affectedHandoffIds) {
          const siblings = remainingRuns.filter((r) => r.handoffId === handoffId);
          if (siblings.length <= 1) continue;

          const withTimestamp = await Promise.all(
            siblings.map(async (s) => ({
              runId: s.runId,
              timestampMs: await getRunTimestampMs(join(dir, '.agent-runs', 'runs', handoffId, s.runId)),
            })),
          );

          // Newest first; keep index 0, remove the rest (the older siblings).
          withTimestamp.sort((a, b) => b.timestampMs - a.timestampMs);

          for (const stale of withTimestamp.slice(1)) {
            const staleRunDir = join(dir, '.agent-runs', 'runs', handoffId, stale.runId);
            await rm(staleRunDir, { recursive: true, force: true });
            report.orphanRuns.push(`${handoffId}/${stale.runId}`);
            report.totalRemoved++;
          }
        }
      }
    }

    return ok(report);
  } catch (err) {
    return fail('CLEANUP_ERROR', 'Cleanup failed unexpectedly.', err);
  }
}

